#!/usr/bin/env python3
# SI disclosure (NASA Space Apps 2026): this file was written with the help of an AI coding
# assistant (Claude, Anthropic) under the direction of the Datanauts Brasil team. The project idea,
# scope and decisions are the team's own. No data or results are generated by AI: every value comes
# from the public sources listed in REFERENCES.md and data/<field>/manifesto.json.
"""
Rotare | coleta de dados para um talhao (Datanauts Brasil, NASA Space Apps 2026)

Coleta, para um ponto (lat, lon), as fontes do projeto e salva tudo em Parquet:

  power      NASA POWER: clima diario (temperatura, chuva, radiacao, umidade, vento)
  power_historico  NASA POWER de 1981 ate o dia anterior ao --inicio (ET0 para safras antigas, ex.: 1997/98)
  oni        NOAA CPC: indice ONI (El Nino / La Nina) por trimestre
  appeears   NASA AppEEARS: NDVI/EVI do MODIS (MOD13Q1) e, se houver, umidade do solo SMAP L4
  hls        NASA HLS (Landsat + Sentinel-2, 30 m) via AppEEARS: NDVI do talhao com mascara de nuvem
  imerg      NASA GPM IMERG Final V07: chuva por satelite (mensal por padrao, diario opcional)
  solo       ISRIC SoilGrids: argila, areia, silte, carbono, pH, densidade, CTC, nitrogenio
  relevo     SRTM 30 m via OpenTopodata: altitude e declividade
  ecocrop    FAO ECOCROP: exigencias de 18 culturas + aptidao de cada uma no talhao por mes de plantio
  calendario_fao  FAO Crop Calendar: tentativa automatica; se falhar, le a planilha manual
  mapbiomas  MapBiomas via Google Earth Engine: uso da terra por ano (opcional)

No fim, junta tudo numa tabela diaria harmonizada (com ET0 de Hargreaves, dias de geada
e calor, ano-safra e fase do ENSO) e grava um manifesto com as referencias para o campo
"References" da pagina do projeto.

Uso rapido:
  pip install -r requirements.txt
  export EARTHDATA_USERNAME=... EARTHDATA_PASSWORD=...    # conta gratis em urs.earthdata.nasa.gov
  python coleta_rotare.py --lat -12.60 --lon -55.95 --inicio 2014-01-01 --fim 2025-12-31

Cada fonte roda isolada: se uma falhar, as outras continuam e o resumo final mostra o que faltou.
"""
from __future__ import annotations

import argparse
import io
import json
import math
import os
import sys
import time
import unicodedata
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field, replace
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

import numpy as np
import pandas as pd
import requests

UA = {"User-Agent": "rotare-datanauts/1.0 (NASA Space Apps 2026)"}
TIMEOUT = 120


# ----------------------------------------------------------------------------------------
# utilidades
# ----------------------------------------------------------------------------------------
@dataclass
class Contexto:
    lat: float
    lon: float
    inicio: date
    fim: date
    saida: Path
    nome: str
    referencias: list = field(default_factory=list)
    resumo: dict = field(default_factory=dict)

    def salvar(self, df: pd.DataFrame, arquivo: str) -> Path:
        caminho = self.saida / arquivo
        df.to_parquet(caminho, index=False)
        df.head(200).to_csv(caminho.with_suffix(".amostra.csv"), index=False)
        return caminho

    def ref(self, nome: str, url: str, licenca: str = "", citacao: str = ""):
        self.referencias.append({"fonte": nome, "url": url, "licenca": licenca, "citacao": citacao})


def log(msg: str):
    print(f"[{datetime.now():%H:%M:%S}] {msg}", flush=True)


def get(url: str, **kw) -> requests.Response:
    """GET com 3 tentativas e espera crescente."""
    kw.setdefault("timeout", TIMEOUT)
    kw.setdefault("headers", UA)
    erro = None
    for tentativa in range(3):
        try:
            r = requests.get(url, **kw)
            if r.status_code in (429, 500, 502, 503, 504):
                raise requests.HTTPError(f"HTTP {r.status_code}")
            r.raise_for_status()
            return r
        except Exception as e:  # noqa: BLE001
            erro = e
            time.sleep(2 * (tentativa + 1))
    raise RuntimeError(f"falha em {url[:90]}...: {erro}")


def carregar_env(arquivo: Path = Path(__file__).with_name(".env")):
    """Le credenciais de um .env ao lado do script (KEY=valor). Nao sobrescreve o que ja estiver no ambiente."""
    if not arquivo.exists():
        return
    for linha in arquivo.read_text(encoding="utf-8").splitlines():
        linha = linha.strip()
        if not linha or linha.startswith("#") or "=" not in linha:
            continue
        k, v = linha.split("=", 1)
        v = v.strip().strip('"').strip("'")
        if v:
            os.environ.setdefault(k.strip(), v)


def credenciais_earthdata() -> tuple[str, str]:
    u, p = os.environ.get("EARTHDATA_USERNAME"), os.environ.get("EARTHDATA_PASSWORD")
    if not u or not p:
        raise RuntimeError("AppEEARS precisa de EARTHDATA_USERNAME e EARTHDATA_PASSWORD no .env (o token nao serve)")
    return u, p


# ----------------------------------------------------------------------------------------
# 1. NASA POWER (clima diario, sem chave)
# ----------------------------------------------------------------------------------------
POWER_PARAMS = {
    "T2M": "temp_media_c",
    "T2M_MAX": "temp_max_c",
    "T2M_MIN": "temp_min_c",
    "PRECTOTCORR": "chuva_power_mm",
    "RH2M": "umidade_rel_pct",
    "WS2M": "vento_2m_ms",
    "ALLSKY_SFC_SW_DWN": "radiacao_mj_m2",
}


def coletar_power(ctx: Contexto) -> pd.DataFrame:
    url = "https://power.larc.nasa.gov/api/temporal/daily/point"
    params = {
        "parameters": ",".join(POWER_PARAMS),
        "community": "AG",
        "latitude": ctx.lat,
        "longitude": ctx.lon,
        "start": ctx.inicio.strftime("%Y%m%d"),
        "end": ctx.fim.strftime("%Y%m%d"),
        "format": "JSON",
        "time-standard": "LST",
    }
    dados = get(url, params=params).json()
    p = dados["properties"]["parameter"]
    df = pd.DataFrame({POWER_PARAMS.get(k, k): pd.Series(v) for k, v in p.items()})
    df.index = pd.to_datetime(df.index, format="%Y%m%d")
    df = df.replace(-999.0, np.nan).rename_axis("data").reset_index()
    ctx.ref(
        "NASA POWER (Prediction Of Worldwide Energy Resources), daily, AG community",
        "https://power.larc.nasa.gov/",
        "Uso livre, com agradecimento",
        "These data were obtained from the NASA Langley Research Center (LaRC) POWER Project "
        "funded through the NASA Earth Science/Applied Science Program.",
    )
    return df


# ----------------------------------------------------------------------------------------
# 2. ONI (El Nino / La Nina), arquivo de texto da NOAA
# ----------------------------------------------------------------------------------------
TRIM_MES_CENTRAL = {"DJF": 1, "JFM": 2, "FMA": 3, "MAM": 4, "AMJ": 5, "MJJ": 6,
                    "JJA": 7, "JAS": 8, "ASO": 9, "SON": 10, "OND": 11, "NDJ": 12}


def ler_oni(texto: str) -> pd.DataFrame:
    linhas = [l.split() for l in texto.strip().splitlines()]
    linhas = [l for l in linhas if len(l) == 4 and l[0] in TRIM_MES_CENTRAL]
    df = pd.DataFrame(linhas, columns=["trimestre", "ano", "sst_total", "oni"])
    df["ano"] = df["ano"].astype(int)
    df[["sst_total", "oni"]] = df[["sst_total", "oni"]].astype(float)
    df["mes_central"] = df["trimestre"].map(TRIM_MES_CENTRAL)
    df["fase"] = np.select([df["oni"] >= 0.5, df["oni"] <= -0.5], ["el_nino", "la_nina"], "neutro")
    return df


def coletar_oni(ctx: Contexto) -> pd.DataFrame:
    url = "https://www.cpc.ncep.noaa.gov/data/indices/oni.ascii.txt"
    df = ler_oni(get(url).text)
    ctx.ref("NOAA CPC Oceanic Nino Index (ONI)",
            "https://www.cpc.ncep.noaa.gov/products/analysis_monitoring/ensostuff/ONI_change.shtml",
            "Dominio publico (NOAA)")
    return df


def enso_por_safra(oni: pd.DataFrame) -> pd.DataFrame:
    """Classifica cada ano-safra (jul a jun) pelo pico do ONI entre ago e mar.
    ano_safra 2023 = jul/2023 a jun/2024."""
    o = oni.copy()
    o["ano_safra"] = np.where(o["mes_central"] >= 7, o["ano"], o["ano"] - 1)
    janela = o[o["mes_central"].isin([8, 9, 10, 11, 12, 1, 2, 3])]
    g = janela.groupby("ano_safra")["oni"].agg(oni_max="max", oni_min="min").reset_index()

    def classe(r):
        if r.oni_max >= 1.5:
            return "el_nino_forte"
        if r.oni_max >= 0.5:
            return "el_nino_fraco_moderado"
        if r.oni_min <= -0.5:
            return "la_nina"
        return "neutro"

    g["enso_safra"] = g.apply(classe, axis=1)
    return g


# ----------------------------------------------------------------------------------------
# 3. AppEEARS (NDVI MODIS e SMAP L4), API REST com login Earthdata
# ----------------------------------------------------------------------------------------
APPEEARS = "https://appeears.earthdatacloud.nasa.gov/api"


def _appeears_token() -> str:
    u, p = credenciais_earthdata()
    r = requests.post(f"{APPEEARS}/login", auth=(u, p), timeout=TIMEOUT, headers=UA)
    r.raise_for_status()
    return r.json()["token"]


def _produto_mais_recente(prefixo: str, catalogo: list[dict]) -> str | None:
    cands = sorted(p["ProductAndVersion"] for p in catalogo if p["ProductAndVersion"].startswith(prefixo + "."))
    return cands[-1] if cands else None


def coletar_appeears(ctx: Contexto, incluir_smap: bool = True, espera_max_min: int = 45) -> dict[str, pd.DataFrame]:
    token = _appeears_token()
    head = {"Authorization": f"Bearer {token}", **UA}

    camadas = [
        {"product": "MOD13Q1.061", "layer": "_250m_16_days_NDVI"},
        {"product": "MOD13Q1.061", "layer": "_250m_16_days_EVI"},
        {"product": "MOD13Q1.061", "layer": "_250m_16_days_pixel_reliability"},
    ]
    if incluir_smap:
        catalogo = get(f"{APPEEARS}/product", headers=head).json()
        smap = _produto_mais_recente("SPL4SMGP", catalogo)
        if smap:
            lay = get(f"{APPEEARS}/product/{smap}", headers=head).json()
            for nome in lay:
                if nome.endswith("sm_rootzone") or nome.endswith("sm_surface"):
                    camadas.append({"product": smap, "layer": nome})
        else:
            log("  SMAP L4 nao encontrado no catalogo do AppEEARS; seguindo so com MODIS")

    saidas: dict[str, pd.DataFrame] = {}
    rotulo = "modis" if incluir_smap else "ndvi"  # tarefa separada: so NDVI chega bem mais rapido
    for nome, df in _appeears_rodar(ctx, head, camadas, rotulo, espera_max_min):
        if "mod13q1" in nome:
            saidas["ndvi_modis"] = _limpar_modis(df)
        elif "spl4smgp" in nome:
            saidas["smap_l4"] = _limpar_smap(df)

    ctx.ref("MODIS/Terra Vegetation Indices 16-Day L3 Global 250m (MOD13Q1 v061), via AppEEARS",
            "https://doi.org/10.5067/MODIS/MOD13Q1.061", "Uso livre (NASA EOSDIS)",
            "Didan, K. (2021). MOD13Q1 MODIS/Terra Vegetation Indices 16-Day L3 Global 250m SIN Grid V061.")
    ctx.ref("AppEEARS (Application for Extracting and Exploring Analysis Ready Samples)",
            "https://appeears.earthdatacloud.nasa.gov/", "Uso livre (NASA LP DAAC)")
    if "smap_l4" in saidas:
        ctx.ref("SMAP L4 Global 3-hourly 9 km Surface and Root Zone Soil Moisture (SPL4SMGP)",
                "https://nsidc.org/data/spl4smgp", "Uso livre (NASA NSIDC DAAC)")
    return saidas


def _appeears_rodar(ctx: Contexto, head: dict, camadas: list[dict], rotulo: str,
                    espera_max_min: int) -> list[tuple[str, pd.DataFrame]]:
    """Envia (ou retoma) uma tarefa de ponto no AppEEARS, espera e devolve os CSVs."""
    estado_arq = ctx.saida / f"appeears_tarefa_{rotulo}.json"
    estado = json.loads(estado_arq.read_text()) if estado_arq.exists() else {}
    chave = f"{ctx.lat},{ctx.lon},{ctx.inicio},{ctx.fim},{sorted(str(c) for c in camadas)}"
    if estado.get("chave") == chave:
        tarefa = estado["task_id"]
        log(f"  retomando tarefa AppEEARS {rotulo}: {tarefa}")
    else:
        corpo = {
            "task_type": "point",
            "task_name": f"rotare_{ctx.nome}_{rotulo}",
            "params": {
                "dates": [{"startDate": ctx.inicio.strftime("%m-%d-%Y"), "endDate": ctx.fim.strftime("%m-%d-%Y")}],
                "layers": camadas,
                "coordinates": [{"id": ctx.nome, "category": "talhao", "latitude": ctx.lat, "longitude": ctx.lon}],
            },
        }
        r = requests.post(f"{APPEEARS}/task", json=corpo, headers=head, timeout=TIMEOUT)
        r.raise_for_status()
        tarefa = r.json()["task_id"]
        estado_arq.write_text(json.dumps({"chave": chave, "task_id": tarefa}))
        log(f"  tarefa AppEEARS {rotulo} enviada: {tarefa} (costuma levar de 2 a 20 min)")

    limite = time.time() + espera_max_min * 60
    while True:
        status = get(f"{APPEEARS}/task/{tarefa}", headers=head).json().get("status")
        if status == "done":
            break
        if status == "error":
            raise RuntimeError(f"AppEEARS retornou erro na tarefa {tarefa}")
        if time.time() > limite:
            raise RuntimeError(f"tarefa {tarefa} ainda em '{status}'. Rode de novo mais tarde: ela sera retomada")
        log(f"  AppEEARS: {status}...")
        time.sleep(30)

    arquivos = get(f"{APPEEARS}/bundle/{tarefa}", headers=head).json()["files"]
    saidas = []
    for f in arquivos:
        if not f["file_name"].endswith(".csv"):
            continue
        conteudo = get(f"{APPEEARS}/bundle/{tarefa}/{f['file_id']}", headers=head, allow_redirects=True).content
        saidas.append((f["file_name"].lower(), pd.read_csv(io.BytesIO(conteudo))))
    return saidas


# ----------------------------------------------------------------------------------------
# 3b. HLS (Landsat + Sentinel-2 harmonizados, 30 m) via AppEEARS: NDVI do talhao
# ----------------------------------------------------------------------------------------
HLS_BANDAS = {"HLSL30": ("B04", "B05"), "HLSS30": ("B04", "B8A")}  # (vermelho, NIR); guia HLS v2.0


def coletar_hls(ctx: Contexto, espera_max_min: int = 60) -> dict[str, pd.DataFrame]:
    token = _appeears_token()
    head = {"Authorization": f"Bearer {token}", **UA}
    catalogo = get(f"{APPEEARS}/product", headers=head).json()
    camadas = []
    for prefixo, (red, nir) in HLS_BANDAS.items():
        prod = _produto_mais_recente(prefixo, catalogo)
        if not prod:
            log(f"  {prefixo} nao encontrado no AppEEARS")
            continue
        disponiveis = set(get(f"{APPEEARS}/product/{prod}", headers=head).json())
        for lay in (red, nir, "Fmask"):
            if lay in disponiveis:
                camadas.append({"product": prod, "layer": lay})
            else:
                log(f"  {prod}: camada {lay} nao encontrada (disponiveis: {sorted(disponiveis)[:12]}...)")
    if not camadas:
        raise RuntimeError("nenhuma camada HLS disponivel")

    partes = []
    for nome, df in _appeears_rodar(ctx, head, camadas, "hls", espera_max_min):
        for prefixo, (red, nir) in HLS_BANDAS.items():
            if prefixo.lower() in nome:
                partes.append(_limpar_hls(df, red, nir, "landsat" if prefixo == "HLSL30" else "sentinel2"))
    if not partes:
        raise RuntimeError("AppEEARS nao devolveu CSV do HLS")
    hls = pd.concat(partes).sort_values("data").reset_index(drop=True)

    ctx.ref("Harmonized Landsat Sentinel-2 (HLS) v2.0, HLSL30 e HLSS30, via AppEEARS",
            "https://hls.gsfc.nasa.gov/", "Uso livre (NASA LP DAAC)",
            "Masek, J., et al. HLS Operational Land Surface Reflectance and TOA Brightness Daily Global 30m v2.0. "
            "NASA EOSDIS LP DAAC.")
    return {"ndvi_hls": hls}


def _limpar_hls(df: pd.DataFrame, red: str, nir: str, sensor: str) -> pd.DataFrame:
    def num(trecho):
        c = _col(df, "_" + trecho)
        s = pd.to_numeric(df[c], errors="coerce") if c else pd.Series(np.nan, index=df.index)
        return s.where(s != -9999)

    r, n, fm = num(red), num(nir), num("Fmask")
    # Fmask: bit1 nuvem, bit2 vizinho de nuvem/sombra, bit3 sombra, bit4 neve/gelo, bit5 agua; 255 = sem dado
    fmi = fm.fillna(255).astype(int)
    ruim = (fmi == 255) | ((fmi & 0b00111110) != 0)
    ndvi = ((n - r) / (n + r)).where(~ruim)
    out = pd.DataFrame({"data": pd.to_datetime(df[_col(df, "Date")]), "sensor": sensor, "ndvi": ndvi,
                        "nuvem_ou_ruim": ruim})
    out.loc[(out["ndvi"] < -1) | (out["ndvi"] > 1), "ndvi"] = np.nan
    return out


def _col(df: pd.DataFrame, trecho: str) -> str | None:
    for c in df.columns:
        if trecho.lower() in c.lower():
            return c
    return None


def _limpar_modis(df: pd.DataFrame) -> pd.DataFrame:
    out = pd.DataFrame({"data": pd.to_datetime(df[_col(df, "Date")])})
    for nome, trecho in [("ndvi", "16_days_NDVI"), ("evi", "16_days_EVI"), ("confiab", "pixel_reliability")]:
        c = _col(df, trecho)
        if c:
            out[nome] = pd.to_numeric(df[c], errors="coerce")
    for v in ("ndvi", "evi"):  # se vier sem escala aplicada (inteiros), converte
        if v in out and out[v].abs().median() > 1.5:
            out[v] = out[v] * 0.0001
    if "confiab" in out:  # 0 = bom, 1 = marginal; 2 neve, 3 nuvem: descarta
        out.loc[out["confiab"] > 1, ["ndvi", "evi"]] = np.nan
    return out.sort_values("data").reset_index(drop=True)


def _limpar_smap(df: pd.DataFrame) -> pd.DataFrame:
    out = pd.DataFrame({"data_hora": pd.to_datetime(df[_col(df, "Date")])})
    for nome, trecho in [("sm_superficie", "sm_surface"), ("sm_raiz", "sm_rootzone")]:
        c = _col(df, trecho)
        if c:
            out[nome] = pd.to_numeric(df[c], errors="coerce").where(lambda s: s >= 0)
    out["data"] = out["data_hora"].dt.normalize()
    return out.groupby("data", as_index=False)[[c for c in ("sm_superficie", "sm_raiz") if c in out]].mean()


# ----------------------------------------------------------------------------------------
# 4. GPM IMERG Final V07 (via earthaccess). Mensal por padrao: leve e cobre 2000 a hoje.
# ----------------------------------------------------------------------------------------
def coletar_imerg(ctx: Contexto, modo: str = "mensal", workers: int = 8) -> pd.DataFrame:
    import earthaccess  # noqa: PLC0415
    import xarray as xr  # noqa: PLC0415

    earthaccess.login(strategy="environment")
    curto = "GPM_3IMERGM" if modo == "mensal" else "GPM_3IMERGDF"
    gran = earthaccess.search_data(short_name=curto, version="07",
                                   temporal=(ctx.inicio.isoformat(), ctx.fim.isoformat()))
    log(f"  IMERG {modo}: {len(gran)} arquivos para ler (so o pixel do talhao)")
    arquivos = earthaccess.open(gran)

    def abrir(f):
        # mensal (HDF5) guarda tudo no grupo "Grid"; o diario (nc4) pode estar na raiz.
        # decode_times=False: o IMERG usa calendario "julian", e a data e calculada a mao abaixo
        for grupo in ("Grid", None):
            try:
                f.seek(0)
                ds = xr.open_dataset(f, engine="h5netcdf", group=grupo, decode_times=False)
                if "precipitation" in ds:
                    return ds
            except (OSError, KeyError, ValueError):
                continue
        raise RuntimeError("variavel 'precipitation' nao encontrada no arquivo IMERG")

    def ler(f):
        ds = abrir(f)
        v = ds["precipitation"].sel(lat=ctx.lat, lon=ctx.lon, method="nearest")
        unid = str(ds["precipitation"].attrs.get("units", ""))
        unid_t = str(ds["time"].attrs.get("units", "seconds since 1980-01-06 00:00:00"))
        passo, _, origem = unid_t.partition(" since ")
        origem = pd.Timestamp(origem.replace(" UTC", "").strip())
        valor_t = float(np.ravel(ds["time"].values)[0])
        t = (origem + pd.to_timedelta(valor_t, unit=passo.strip()[0].lower())).normalize()  # s, m, h ou d
        return t, float(v.values.squeeze()), unid

    with ThreadPoolExecutor(max_workers=workers) as ex:
        linhas = list(ex.map(ler, arquivos))

    df = pd.DataFrame(linhas, columns=["data", "valor", "unidade"]).sort_values("data")
    if modo == "mensal":
        horas = df["data"].dt.days_in_month * 24
        df["chuva_imerg_mm"] = np.where(df["unidade"].str.contains("hr"), df["valor"] * horas, df["valor"])
    else:
        df["chuva_imerg_mm"] = np.where(df["unidade"].str.contains("hr"), df["valor"] * 24, df["valor"])
    ctx.ref(f"GPM IMERG Final Precipitation L3 V07 ({curto})",
            "https://gpm.nasa.gov/data/imerg", "Uso livre (NASA GES DISC)",
            "Huffman, G.J., et al. GPM IMERG Final Precipitation L3, V07. NASA GES DISC.")
    return df[["data", "chuva_imerg_mm"]].reset_index(drop=True)


# ----------------------------------------------------------------------------------------
# 5. SoilGrids (ISRIC): REST e, se estiver fora do ar, WCS (GeoTIFF)
# ----------------------------------------------------------------------------------------
SOLO_PROPS = ["clay", "sand", "silt", "soc", "phh2o", "bdod", "cec", "nitrogen"]
SOLO_PROF = ["0-5cm", "5-15cm", "15-30cm", "30-60cm", "60-100cm"]
SOLO_FATOR = {"clay": 10, "sand": 10, "silt": 10, "soc": 10, "phh2o": 10, "bdod": 100, "cec": 10, "nitrogen": 100}
SOLO_UNID = {"clay": "%", "sand": "%", "silt": "%", "soc": "g/kg", "phh2o": "pH", "bdod": "kg/dm3",
             "cec": "cmol(c)/kg", "nitrogen": "g/kg"}


def coletar_solo(ctx: Contexto) -> pd.DataFrame:
    try:
        df = _solo_rest(ctx)
        via = "REST"
    except Exception as e:  # noqa: BLE001
        log(f"  SoilGrids REST indisponivel ({e}); tentando WCS")
        df = _solo_wcs(ctx)
        via = "WCS"
    df["via"] = via
    ctx.ref("ISRIC SoilGrids 2.0 (250 m)", "https://www.isric.org/explore/soilgrids", "CC BY 4.0",
            "Poggio, L., et al. (2021). SoilGrids 2.0. SOIL, 7, 217-240. https://doi.org/10.5194/soil-7-217-2021")
    return df


def _solo_rest(ctx: Contexto) -> pd.DataFrame:
    url = "https://rest.isric.org/soilgrids/v2.0/properties/query"
    params = [("lon", ctx.lon), ("lat", ctx.lat), ("value", "mean")]
    params += [("property", p) for p in SOLO_PROPS] + [("depth", d) for d in SOLO_PROF]
    js = get(url, params=params, timeout=60).json()
    linhas = []
    for camada in js["properties"]["layers"]:
        fator = camada["unit_measure"]["d_factor"]
        for prof in camada["depths"]:
            bruto = prof["values"].get("mean")
            linhas.append({"propriedade": camada["name"], "profundidade": prof["label"],
                           "valor": None if bruto is None else bruto / fator,
                           "unidade": SOLO_UNID.get(camada["name"], "")})
    if all(l["valor"] is None for l in linhas):
        raise RuntimeError("sem valores (ponto em agua ou area urbana?)")
    return pd.DataFrame(linhas)


def _solo_wcs(ctx: Contexto) -> pd.DataFrame:
    import rasterio  # noqa: PLC0415
    from rasterio.io import MemoryFile  # noqa: PLC0415

    d = 0.004  # ~450 m de janela em volta do ponto
    linhas = []
    for p in SOLO_PROPS:
        for prof in SOLO_PROF:
            params = [
                ("map", f"/map/{p}.map"), ("SERVICE", "WCS"), ("VERSION", "2.0.1"), ("REQUEST", "GetCoverage"),
                ("COVERAGEID", f"{p}_{prof}_mean"), ("FORMAT", "image/tiff"),
                ("SUBSET", f"long({ctx.lon - d},{ctx.lon + d})"), ("SUBSET", f"lat({ctx.lat - d},{ctx.lat + d})"),
                ("SUBSETTINGCRS", "http://www.opengis.net/def/crs/EPSG/0/4326"),
                ("OUTPUTCRS", "http://www.opengis.net/def/crs/EPSG/0/4326"),
            ]
            r = get("https://maps.isric.org/mapserv", params=params, timeout=90)
            with MemoryFile(r.content) as mf, mf.open() as src:
                a = src.read(1).astype(float)
                if src.nodata is not None:
                    a[a == src.nodata] = np.nan
                a[a < 0] = np.nan
                bruto = np.nanmedian(a) if np.isfinite(a).any() else np.nan
            linhas.append({"propriedade": p, "profundidade": prof, "valor": bruto / SOLO_FATOR[p],
                           "unidade": SOLO_UNID[p]})
    _ = rasterio  # import usado so para garantir dependencia
    return pd.DataFrame(linhas)


# ----------------------------------------------------------------------------------------
# 6. Relevo SRTM 30 m (OpenTopodata): altitude e declividade numa grade 3x3
# ----------------------------------------------------------------------------------------
def declividade_horn(z: np.ndarray, dx: float, dy: float) -> float:
    """Declividade (%) pelo metodo de Horn numa janela 3x3 (linhas de norte para sul)."""
    a, b, c = z[0]
    d, _, f = z[1]
    g, h, i = z[2]
    dzdx = ((c + 2 * f + i) - (a + 2 * d + g)) / (8 * dx)
    dzdy = ((g + 2 * h + i) - (a + 2 * b + c)) / (8 * dy)
    return 100 * math.hypot(dzdx, dzdy)


def coletar_relevo(ctx: Contexto, passo_m: float = 30.0) -> pd.DataFrame:
    dlat = passo_m / 111_320
    dlon = passo_m / (111_320 * math.cos(math.radians(ctx.lat)))
    pontos = [(ctx.lat + dlat * (1 - r), ctx.lon + dlon * (c - 1)) for r in range(3) for c in range(3)]
    locs = "|".join(f"{la:.6f},{lo:.6f}" for la, lo in pontos)
    js = get("https://api.opentopodata.org/v1/srtm30m", params={"locations": locs}).json()
    z = np.array([r["elevation"] for r in js["results"]], dtype=float).reshape(3, 3)
    decl = declividade_horn(z, passo_m, passo_m)
    ctx.ref("NASA SRTM 1 Arc-Second Global (30 m), via OpenTopodata",
            "https://doi.org/10.5066/F7PR7TFT", "Dominio publico (NASA/USGS)")
    return pd.DataFrame([{"altitude_m": float(z[1, 1]), "declividade_pct": round(decl, 2),
                          "risco_erosao_relevo": "alto" if decl >= 8 else "medio" if decl >= 3 else "baixo"}])


