# 6b. ECOCROP (FAO): exigencias das culturas + aptidao de cada cultura no talhao por mes de plantio
# ----------------------------------------------------------------------------------------
ECOCROP_URL = "https://raw.githubusercontent.com/openclim/ecocrop/main/EcoCrop_DB.csv"
ECOCROP_LOCAL = Path(__file__).with_name("ecocrop_culturas.csv")  # recorte da mesma base, ja no pacote
ECOCROP_NOMES = {
    "Glycine max": "soja", "Zea mays": "milho", "Sorghum bicolor": "sorgo", "Gossypium hirsutum": "algodao",
    "Pennisetum glaucum": "milheto", "Crotalaria juncea": "crotalaria_juncea",
    "Crotalaria spectabilis": "crotalaria_spectabilis", "Brachiaria ruziziensis": "braquiaria_ruziziensis",
    "Brachiaria brizantha": "braquiaria_brizantha", "Phaseolus vulgaris": "feijao", "Vigna unguiculata": "feijao_caupi",
    "Cajanus cajan": "feijao_guandu", "Triticum aestivum": "trigo", "Avena sativa": "aveia",
    "Helianthus annuus": "girassol", "Arachis hypogaea": "amendoim", "Raphanus sativus": "nabo_forrageiro",
    "Sesamum indicum": "gergelim",
}


def trapezio(x: float, a: float, b: float, c: float, d: float) -> float:
    """Aptidao 0 a 1: zero fora de [a, d], um entre [b, c], linear nas rampas (modelo ECOCROP)."""
    if any(pd.isna(v) for v in (x, a, b, c, d)) or x <= a or x >= d:
        return 0.0 if not pd.isna(x) else np.nan
    if x < b:
        return (x - a) / (b - a)
    if x <= c:
        return 1.0
    return (d - x) / (d - c)


def carregar_ecocrop() -> tuple[pd.DataFrame, str]:
    try:
        bruto = pd.read_csv(io.BytesIO(get(ECOCROP_URL, timeout=60).content), encoding="latin-1")
        base = bruto[bruto["ScientificName"].isin(ECOCROP_NOMES)].copy()
        base.insert(0, "cultura", base["ScientificName"].map(ECOCROP_NOMES))
        via = "github openclim/ecocrop"
    except Exception as e:  # noqa: BLE001
        log(f"  download do ECOCROP falhou ({e}); usando o recorte local")
        base, via = pd.read_csv(ECOCROP_LOCAL), "recorte local"
    return base.sort_values("cultura").reset_index(drop=True), via


def coletar_ecocrop(ctx: Contexto, tabelas: dict, ciclo_ref_dias: int = 120) -> dict[str, pd.DataFrame]:
    base, via = carregar_ecocrop()
    ctx.ref("FAO ECOCROP (parametros das culturas), base em github.com/openclim/ecocrop",
            "https://ecocrop.apps.fao.org/ecocrop/srv/en/home", "FAO; recorte sob Open Government Licence v3",
            "FAO. ECOCROP database. Modelo de aptidao: Hijmans, R.J., et al. (2001). Plant Genetic Resources "
            "Newsletter 127: 1-5.")
    saidas = {"ecocrop_parametros": base}
    if "power" not in tabelas:
        log("  sem NASA POWER: salvando so os parametros (aptidao precisa do clima)")
        return saidas

    p = tabelas["power"].copy()
    p["ano"], p["mes"] = p["data"].dt.year, p["data"].dt.month
    mensal = p.groupby(["ano", "mes"]).agg(t=("temp_media_c", "mean"), tmin_abs=("temp_min_c", "min"),
                                          chuva=("chuva_power_mm", "sum"), n=("data", "count")).reset_index()
    mensal = mensal[mensal["n"] >= 25]
    clima = mensal.groupby("mes").agg(t=("t", "mean"), tmin_abs=("tmin_abs", "mean"), chuva=("chuva", "mean"))

    ph = np.nan
    if "solo" in tabelas:
        s = tabelas["solo"]
        s = s[(s["propriedade"] == "phh2o") & s["profundidade"].isin(["0-5cm", "5-15cm", "15-30cm"])]
        if len(s):
            ph = float(np.average(s["valor"], weights=[5, 10, 15][: len(s)]))

    linhas = []
    for _, c in base.iterrows():
        dias = int(np.clip(ciclo_ref_dias, c["GMIN"] if pd.notna(c["GMIN"]) else 30,
                           c["GMAX"] if pd.notna(c["GMAX"]) else 365))
        n_meses = max(1, math.ceil(dias / 30))
        for m0 in range(1, 13):
            meses = [((m0 - 1 + k) % 12) + 1 for k in range(n_meses)]
            cl = clima.loc[meses]
            apt_t = min(trapezio(t, c["TMIN"], c["TOPMN"], c["TOPMX"], c["TMAX"]) for t in cl["t"])
            mata_geada = pd.notna(c["KTMP"]) and float(cl["tmin_abs"].min()) <= float(c["KTMP"])
            if mata_geada:
                apt_t = 0.0
            chuva_ciclo = float(cl["chuva"].sum())
            apt_c = trapezio(chuva_ciclo, c["RMIN"], c["ROPMN"], c["ROPMX"], c["RMAX"])
            apt_ph = trapezio(ph, c["PHMIN"], c["PHOPMN"], c["PHOPMX"], c["PHMAX"]) if pd.notna(ph) else np.nan
            notas = [v for v in (apt_t, apt_c, apt_ph) if pd.notna(v)]
            linhas.append({"cultura": c["cultura"], "mes_plantio": m0, "ciclo_dias": dias,
                           "temp_media_ciclo_c": round(float(cl["t"].mean()), 1),
                           "chuva_ciclo_mm": round(chuva_ciclo), "ph_solo": None if pd.isna(ph) else round(ph, 2),
                           "aptidao_temp": round(apt_t, 2), "aptidao_chuva": round(apt_c, 2),
                           "aptidao_ph": None if pd.isna(apt_ph) else round(apt_ph, 2), "risco_geada_letal": mata_geada,
                           "aptidao": round(min(notas), 2) if notas else np.nan})
    saidas["aptidao_ecocrop"] = pd.DataFrame(linhas)
    log(f"  ECOCROP via {via}: {len(base)} culturas, aptidao por mes de plantio calculada")
    return saidas


