# 6c. FAO Crop Calendar: tentativa automatica + planilha manual de reserva
# ----------------------------------------------------------------------------------------
CALENDARIO_MANUAL = Path(__file__).with_name("calendario_fao_manual.csv")
CALENDARIO_COLS = ["cultura", "regiao_ou_zona", "plantio_inicio", "plantio_fim", "colheita_inicio",
                   "colheita_fim", "fonte_url", "observacao"]


def _texto_aninhado(v):
    if isinstance(v, dict):
        return {k: _texto_aninhado(x) for k, x in v.items()}
    if isinstance(v, (list, tuple, np.ndarray)):
        return [_texto_aninhado(x) for x in v]
    return None if v is None else str(v)


def coletar_calendario_fao(ctx: Contexto, pais: str = "BR") -> pd.DataFrame:
    """O FAO Crop Calendar nao publica API documentada. Tentamos o servico que o site usa; se nao
    responder, lemos a planilha manual preenchida pelo time a partir de cropcalendar.apps.fao.org."""
    url = f"https://api-cropcalendar.apps.fao.org/api/v1/countries/{pais}/cropCalendar"
    df = None
    try:
        js = get(url, params={"language": "en"}, timeout=20).json()
        df = pd.json_normalize(js if isinstance(js, list) else js.get("data", js))
        if df.empty:
            df = None
        else:
            df["fonte_url"] = url
            if "sessions" in df:  # dia e mes vem ora como numero, ora como texto: padroniza em texto
                df["sessions"] = df["sessions"].map(_texto_aninhado)
    except Exception as e:  # noqa: BLE001
        log(f"  calendario FAO automatico indisponivel ({str(e)[:80]}); usando a planilha manual")
    if df is None and pais != "BR":
        raise RuntimeError(f"o FAO Crop Calendar nao tem dados para o pais {pais}")
    if df is None:
        if not CALENDARIO_MANUAL.exists():
            pd.DataFrame(columns=CALENDARIO_COLS).to_csv(CALENDARIO_MANUAL, index=False)
        df = pd.read_csv(CALENDARIO_MANUAL)
        if df.dropna(how="all").empty:
            raise RuntimeError(f"preencha {CALENDARIO_MANUAL.name} com os dados de cropcalendar.apps.fao.org "
                               "(ou use o ZARC, que e mais detalhado para o Brasil)")
    ctx.ref("FAO Crop Calendar", "https://cropcalendar.apps.fao.org/", "FAO")
    return df


# ----------------------------------------------------------------------------------------
# 6d. ZARC (MAPA): tabua de risco de plantio por decendio, para o municipio do talhao
# ----------------------------------------------------------------------------------------
ZARC_CKAN = ("https://dados.agricultura.gov.br/api/3/action/package_show"
             "?id=tabua-de-risco-zoneamento-agricola-de-risco-climatico")
# codigos do dicionario de dados oficial (dicionario-de-dados-tabua-de-risco-2026.pdf)
ZARC_CICLO = {13: "perene", 19: "semiperene", 20: "grupo_I", 21: "grupo_II", 22: "grupo_III",
              24: "grupo_IV", 25: "grupo_V", 26: "grupo_VI"}
ZARC_SOLO = {1: "arenoso", 2: "textura_media", 3: "argiloso", 11: "AD1", 12: "AD2", 13: "AD3",
             14: "AD4", 15: "AD5", 16: "AD6"}  # AD = classe de agua disponivel (1 menor, 6 maior)


def _sem_acento(t: str) -> str:
    return unicodedata.normalize("NFKD", str(t)).encode("ascii", "ignore").decode().lower().strip()


def municipio_ibge(lat: float, lon: float) -> tuple[str, str, str]:
    """(geocodigo IBGE, nome, UF) do ponto: OpenStreetMap acha o nome, a API do IBGE da o codigo."""
    js = get("https://nominatim.openstreetmap.org/reverse",
             params={"lat": lat, "lon": lon, "format": "jsonv2", "zoom": 10, "addressdetails": 1}).json()
    end = js.get("address", {})
    nome = end.get("city") or end.get("town") or end.get("municipality") or end.get("village")
    uf = str(end.get("ISO3166-2-lvl4", "")).split("-")[-1]
    if not nome or len(uf) != 2:
        raise RuntimeError(f"municipio nao identificado para ({lat}, {lon}); use --geocodigo")
    for m in get(f"https://servicodados.ibge.gov.br/api/v1/localidades/estados/{uf}/municipios").json():
        if _sem_acento(m["nome"]) == _sem_acento(nome):
            return str(m["id"]), m["nome"], uf
    raise RuntimeError(f"'{nome}/{uf}' nao encontrado no IBGE; use --geocodigo")


_GEOCODIGO: dict = {}


def geocodigo_do_ponto(ctx: Contexto, geocodigo: str | None = None) -> str:
    if geocodigo:
        return str(geocodigo)
    chave = (ctx.lat, ctx.lon)
    if chave not in _GEOCODIGO:
        cod, nome, uf = municipio_ibge(ctx.lat, ctx.lon)
        log(f"  municipio do ponto: {nome}/{uf} (IBGE {cod})")
        _GEOCODIGO[chave] = cod
    return _GEOCODIGO[chave]


def coletar_zarc(ctx: Contexto, geocodigo: str | None = None) -> pd.DataFrame:
    geocodigo = geocodigo_do_ponto(ctx, geocodigo)
    recursos = get(ZARC_CKAN).json()["result"]["resources"]
    csvs = [(r["name"], r["url"]) for r in recursos if str(r.get("format", "")).upper() == "CSV"]
    alvo = f";{geocodigo};".encode()

    partes = []
    for nome_rec, url in csvs:
        try:
            cab, linhas = b"", []
            with requests.get(url, stream=True, timeout=TIMEOUT, headers=UA) as r:
                r.raise_for_status()
                for i, l in enumerate(r.iter_lines(chunk_size=1 << 20)):
                    if i == 0:
                        cab = l
                    elif alvo in l:
                        linhas.append(l)
            log(f"  {nome_rec}: {len(linhas)} linhas do municipio")
            if linhas:
                bruto = b"\n".join([cab] + linhas)
                try:  # as tabelas do MAPA vem ora em UTF-8, ora em Latin-1 (cp1252)
                    texto = bruto.decode("utf-8-sig")
                except UnicodeDecodeError:
                    texto = bruto.decode("cp1252", errors="replace")
                partes.append(pd.read_csv(io.StringIO(texto), sep=";", dtype={"geocodigo": str}))
        except Exception as e:  # noqa: BLE001
            log(f"  {nome_rec} falhou ({str(e)[:80]}); seguindo com as outras safras")
    if not partes:
        raise RuntimeError(f"nenhuma linha do ZARC para o municipio {geocodigo}")

    b = pd.concat(partes, ignore_index=True)
    decs = [f"dec{i}" for i in range(1, 37)]
    ini = pd.to_numeric(b["SafraIni"], errors="coerce").astype("Int64")
    fim = pd.to_numeric(b["SafraFin"], errors="coerce").astype("Int64")
    b["safra"] = np.where(ini.isna(), "sem_safra", ini.astype(str) + "/" + fim.astype(str))
    b["ciclo"] = b["Cod_Ciclo"].map(ZARC_CICLO).fillna(b["Cod_Ciclo"].astype(str))
    b["solo"] = b["Cod_Solo"].map(ZARC_SOLO).fillna(b["Cod_Solo"].astype(str))
    ids = {"safra": "safra", "Nome_cultura": "cultura", "ciclo": "ciclo", "solo": "solo",
           "Nome_Outros_Manejos": "manejo", "Nome_Clima": "clima", "geocodigo": "geocodigo",
           "municipio": "municipio", "UF": "uf", "Portaria": "portaria"}
    longo = b.melt(id_vars=list(ids), value_vars=decs, var_name="decendio", value_name="risco_pct")
    longo = longo.rename(columns=ids)
    longo["risco_pct"] = pd.to_numeric(longo["risco_pct"], errors="coerce")
    longo = longo[longo["risco_pct"] > 0].copy()  # 0 = plantio nao indicado naquele decendio
    longo["decendio"] = longo["decendio"].str[3:].astype(int)
    longo["mes"] = (longo["decendio"] - 1) // 3 + 1
    longo["dia_inicio"] = longo["decendio"].map(lambda d: (1, 11, 21)[(d - 1) % 3])
    ctx.ref("MAPA, Zoneamento Agricola de Risco Climatico (ZARC), Tabua de Risco",
            "https://dados.agricultura.gov.br/dataset/tabua-de-risco-zoneamento-agricola-de-risco-climatico",
            "CC BY", "Brasil. Ministerio da Agricultura e Pecuaria. Zoneamento Agricola de Risco Climatico.")
    ctx.ref("IBGE, API de localidades; OpenStreetMap Nominatim (identificacao do municipio)",
            "https://servicodados.ibge.gov.br/api/docs/localidades", "IBGE: dados publicos; OSM: ODbL")
    return longo.sort_values(["safra", "cultura", "ciclo", "solo", "decendio"]).reset_index(drop=True)


# ----------------------------------------------------------------------------------------
# 6e. CHIRPS (UCSB/USGS): chuva diaria observada desde 1981, via Google Earth Engine
# ----------------------------------------------------------------------------------------
def coletar_chirps(ctx: Contexto, tabelas: dict, inicio: str = "1981-01-01") -> dict[str, pd.DataFrame]:
    """Chuva diaria de satelite + estacoes (~5 km). Cobre o El Nino de 1997/98, que o IMERG (2000+) nao cobre.
    Baixa ano a ano para nao estourar o limite de cada consulta do Earth Engine."""
    import ee  # noqa: PLC0415

    ee.Initialize(project=os.environ.get("EE_PROJECT"))
    ponto = ee.Geometry.Point([ctx.lon, ctx.lat])
    col = ee.ImageCollection("UCSB-CHG/CHIRPS/DAILY").select("precipitation")
    partes = []
    for ano in range(date.fromisoformat(inicio).year, ctx.fim.year + 1):
        ini, fim = max(date(ano, 1, 1), date.fromisoformat(inicio)), min(date(ano, 12, 31), ctx.fim)
        r = col.filterDate(ini.isoformat(), (pd.Timestamp(fim) + pd.Timedelta(days=1)).date().isoformat()) \
            .getRegion(ponto, 5566).getInfo()
        if len(r) > 1:
            partes.append(pd.DataFrame(r[1:], columns=r[0]))
    if not partes:
        raise RuntimeError("CHIRPS sem dados para o ponto/periodo")
    b = pd.concat(partes, ignore_index=True)
    df = pd.DataFrame({"data": pd.to_datetime(b["time"], unit="ms").dt.normalize(),
                       "chuva_chirps_mm": pd.to_numeric(b["precipitation"], errors="coerce").round(2)})
    df = df.drop_duplicates("data").sort_values("data").reset_index(drop=True)

    # resumo por ano-safra (jul a jun) para o modo El Nino com anos antigos (1997/98, 2015/16, 2023/24)
    s = df.assign(ano_safra=np.where(df["data"].dt.month >= 7, df["data"].dt.year, df["data"].dt.year - 1))
    safras = s.groupby("ano_safra").agg(chuva_chirps_mm=("chuva_chirps_mm", "sum"),
                                        dias=("data", "count")).reset_index()
    safras["chuva_chirps_mm"] = safras["chuva_chirps_mm"].round(1)
    safras["safra_completa"] = safras["dias"] >= 360
    if "oni" in tabelas:
        safras = safras.merge(enso_por_safra(tabelas["oni"]), on="ano_safra", how="left")
    ctx.ref("CHIRPS v2.0 daily precipitation (UCSB-CHG), via Google Earth Engine",
            "https://www.chc.ucsb.edu/data/chirps", "Dominio publico (CC0)",
            "Funk, C., et al. (2015). The climate hazards infrared precipitation with stations. "
            "Scientific Data, 2, 150066. https://doi.org/10.1038/sdata.2015.66")
    return {"chirps": df, "chirps_safras": safras}


# ----------------------------------------------------------------------------------------
# 6f. IBGE SIDRA, Producao Agricola Municipal (PAM, tabela 1612): area, producao e produtividade
# ----------------------------------------------------------------------------------------
SIDRA_PRODUTOS = {2713: "soja", 2711: "milho", 2689: "algodao_herbaceo", 2714: "sorgo", 2702: "feijao",
                  109179: "girassol", 2692: "arroz"}
SIDRA_VARIAVEIS = {109: "area_plantada_ha", 216: "area_colhida_ha", 214: "producao_t", 112: "rendimento_kg_ha"}


def coletar_sidra(ctx: Contexto, geocodigo: str | None = None) -> pd.DataFrame:
    """Dado oficial de safra do municipio, ano a ano (1974+). Serve para o backtest: os anos que o motor
    marca como de risco foram mesmo anos de quebra? Atencao: o milho da PAM soma 1a e 2a safra."""
    geocodigo = geocodigo_do_ponto(ctx, geocodigo)
    url = (f"https://apisidra.ibge.gov.br/values/t/1612/n6/{geocodigo}"
           f"/v/{','.join(map(str, SIDRA_VARIAVEIS))}/p/all/c81/{','.join(map(str, SIDRA_PRODUTOS))}")
    js = get(url, timeout=120).json()
    b = pd.DataFrame(js[1:])
    if b.empty:
        raise RuntimeError(f"SIDRA sem dados para o municipio {geocodigo}")
    b["valor"] = pd.to_numeric(b["V"], errors="coerce")  # "-", "..." e "X" viram vazio
    b["variavel"] = b["D2C"].astype(int).map(SIDRA_VARIAVEIS)
    b["produto"] = b["D4C"].astype(int).map(SIDRA_PRODUTOS)
    df = (b.pivot_table(index=["D3C", "produto"], columns="variavel", values="valor", aggfunc="first")
          .reset_index().rename(columns={"D3C": "ano_colheita"}))
    df.columns.name = None
    df["ano_colheita"] = df["ano_colheita"].astype(int)
    # colheita em Y corresponde ao ano-safra Y-1 (jul/Y-1 a jun/Y), a mesma convencao das outras tabelas
    df["ano_safra"] = df["ano_colheita"] - 1
    df["rendimento_sc_ha"] = (df["rendimento_kg_ha"] / 60).round(1)  # saca de 60 kg
    df["municipio"] = b["D1N"].iloc[0]
    df["geocodigo"] = geocodigo
    ctx.ref("IBGE, Producao Agricola Municipal (PAM), tabela 1612 (SIDRA)",
            "https://sidra.ibge.gov.br/tabela/1612", "Dados publicos (IBGE)",
            "IBGE. Producao Agricola Municipal. Tabela 1612. https://sidra.ibge.gov.br/tabela/1612")
    return df.sort_values(["produto", "ano_colheita"]).reset_index(drop=True)


# ----------------------------------------------------------------------------------------
# 7. MapBiomas (Google Earth Engine), opcional
# ----------------------------------------------------------------------------------------
MAPBIOMAS_CLASSES = {  # confira na legenda da colecao usada
    3: "formacao_florestal", 4: "savana", 9: "silvicultura", 12: "campo", 15: "pastagem",
    20: "cana", 21: "mosaico_usos", 24: "urbano", 33: "agua", 39: "soja", 40: "arroz",
    41: "outras_temporarias", 46: "cafe", 47: "citrus", 48: "outras_perenes", 62: "algodao",
}


def coletar_mapbiomas(ctx: Contexto, asset: str) -> pd.DataFrame:
    import ee  # noqa: PLC0415

    ee.Initialize(project=os.environ.get("EE_PROJECT"))
    img = ee.Image(asset)
    vals = img.reduceRegion(ee.Reducer.first(), ee.Geometry.Point([ctx.lon, ctx.lat]), 30).getInfo()
    linhas = []
    for banda, classe in sorted(vals.items()):
        ano = "".join(ch for ch in banda if ch.isdigit())[-4:]
        if classe is not None and ano:
            linhas.append({"ano": int(ano), "classe_id": int(classe),
                           "classe": MAPBIOMAS_CLASSES.get(int(classe), f"classe_{int(classe)}")})
    ctx.ref("MapBiomas Brasil, cobertura e uso da terra", "https://brasil.mapbiomas.org/", "CC BY 4.0",
            "Projeto MapBiomas. Colecao de mapas anuais de cobertura e uso da terra do Brasil.")
    return pd.DataFrame(linhas)


# ----------------------------------------------------------------------------------------
# 7b. Dados NASA pelo Google Earth Engine (global, sem fila): MODIS NDVI, SMAP L4, IMERG mensal e
#     uso da terra MODIS (MCD12Q1). Mesmos produtos da NASA que o AppEEARS entrega, em segundos.
# ----------------------------------------------------------------------------------------
def _ee():
    import ee  # noqa: PLC0415

    ee.Initialize(project=os.environ.get("EE_PROJECT"))
    return ee


def _ee_regiao(col, ponto, escala: int) -> pd.DataFrame:
    r = col.getRegion(ponto, escala).getInfo()
    return pd.DataFrame(r[1:], columns=r[0]) if len(r) > 1 else pd.DataFrame()


def coletar_modis_gee(ctx: Contexto, inicio: str = "2000-01-01") -> pd.DataFrame:
    """MOD13Q1 v061 (NDVI e EVI de 16 dias, 250 m) desde 2000. SummaryQA: 0 bom, 1 marginal, 2 neve, 3 nuvem."""
    ee = _ee()
    ponto = ee.Geometry.Point([ctx.lon, ctx.lat])
    col = ee.ImageCollection("MODIS/061/MOD13Q1").filterDate(inicio, (ctx.fim + timedelta(days=1)).isoformat()) \
        .select(["NDVI", "EVI", "SummaryQA"])
    b = _ee_regiao(col, ponto, 250)
    if b.empty:
        raise RuntimeError("MODIS sem dados para o ponto")
    out = pd.DataFrame({"data": pd.to_datetime(b["time"], unit="ms").dt.normalize(),
                        "ndvi": pd.to_numeric(b["NDVI"], errors="coerce") * 0.0001,
                        "evi": pd.to_numeric(b["EVI"], errors="coerce") * 0.0001,
                        "confiab": pd.to_numeric(b["SummaryQA"], errors="coerce")})
    out.loc[out["confiab"] > 1, ["ndvi", "evi"]] = np.nan
    out[["ndvi", "evi"]] = out[["ndvi", "evi"]].round(4)
    ctx.ref("MODIS/Terra Vegetation Indices 16-Day L3 Global 250m (MOD13Q1 v061), via Google Earth Engine",
            "https://doi.org/10.5067/MODIS/MOD13Q1.061", "Uso livre (NASA EOSDIS)",
            "Didan, K. (2021). MOD13Q1 MODIS/Terra Vegetation Indices 16-Day L3 Global 250m SIN Grid V061.")
    return out.drop_duplicates("data").sort_values("data").reset_index(drop=True)


def coletar_smap_gee(ctx: Contexto) -> pd.DataFrame:
    """SMAP L4 (SPL4SMGP v008, 3 em 3 horas, 9 km) desde abr/2015, media diaria.
    Mes a mes e em paralelo: um ano inteiro de imagens de 3 horas estoura a memoria do Earth Engine."""
    ee = _ee()
    ponto = ee.Geometry.Point([ctx.lon, ctx.lat])
    col = ee.ImageCollection("NASA/SMAP/SPL4SMGP/008").select(["sm_surface", "sm_rootzone"])
    meses = pd.date_range(f"{max(2015, ctx.inicio.year)}-04-01", ctx.fim, freq="MS")

    def mes(m):
        return _ee_regiao(col.filterDate(m.strftime("%Y-%m-%d"), (m + pd.offsets.MonthBegin(1)).strftime("%Y-%m-%d")),
                          ponto, 11000)

    with ThreadPoolExecutor(max_workers=6) as ex:
        partes = [b for b in ex.map(mes, meses) if not b.empty]
    if not partes:
        raise RuntimeError("SMAP sem dados para o ponto")
    b = pd.concat(partes, ignore_index=True)
    d = pd.DataFrame({"data": pd.to_datetime(b["time"], unit="ms").dt.normalize(),
                      "sm_superficie": pd.to_numeric(b["sm_surface"], errors="coerce"),
                      "sm_raiz": pd.to_numeric(b["sm_rootzone"], errors="coerce")})
    d = d.groupby("data", as_index=False).mean().round(4)
    ctx.ref("SMAP L4 Global 3-hourly 9 km Surface and Root Zone Soil Moisture (SPL4SMGP v008), via Google Earth Engine",
            "https://nsidc.org/data/spl4smgp", "Uso livre (NASA NSIDC DAAC)",
            "Reichle, R., et al. SMAP L4 Global 3-hourly 9 km EASE-Grid Surface and Root Zone Soil Moisture. NSIDC DAAC.")
    return d


def coletar_imerg_gee(ctx: Contexto) -> pd.DataFrame:
    """GPM IMERG Final V07 mensal (mm/h no produto) convertido para mm/mes."""
    ee = _ee()
    ponto = ee.Geometry.Point([ctx.lon, ctx.lat])
    col = ee.ImageCollection("NASA/GPM_L3/IMERG_MONTHLY_V07").select("precipitation") \
        .filterDate(ctx.inicio.isoformat(), (ctx.fim + timedelta(days=1)).isoformat())
    b = _ee_regiao(col, ponto, 11132)
    if b.empty:
        raise RuntimeError("IMERG sem dados para o ponto")
    data = pd.to_datetime(b["time"], unit="ms").dt.normalize()
    horas = data.dt.days_in_month * 24
    df = pd.DataFrame({"data": data,
                       "chuva_imerg_mm": (pd.to_numeric(b["precipitation"], errors="coerce") * horas).round(1)})
    ctx.ref("GPM IMERG Final Precipitation L3 Monthly V07, via Google Earth Engine",
            "https://gpm.nasa.gov/data/imerg", "Uso livre (NASA GES DISC)",
            "Huffman, G.J., et al. GPM IMERG Final Precipitation L3 1 month 0.1 degree x 0.1 degree V07. NASA GES DISC.")
    return df.drop_duplicates("data").sort_values("data").reset_index(drop=True)


IGBP = {1: "floresta_conifera_perene", 2: "floresta_latifoliada_perene", 3: "floresta_conifera_decidua",
        4: "floresta_latifoliada_decidua", 5: "floresta_mista", 6: "arbustos_densos", 7: "arbustos_abertos",
        8: "savana_arborizada", 9: "savana", 10: "pastagem_campo", 11: "area_umida", 12: "lavoura",
        13: "urbano", 14: "mosaico_lavoura_vegetacao", 15: "neve_gelo", 16: "solo_exposto", 17: "agua"}


def coletar_uso_terra_gee(ctx: Contexto) -> pd.DataFrame:
    """MODIS MCD12Q1 v061, classificacao IGBP (LC_Type1), anual desde 2001, 500 m. 12 = lavoura."""
    ee = _ee()
    b = _ee_regiao(ee.ImageCollection("MODIS/061/MCD12Q1").select("LC_Type1"),
                   ee.Geometry.Point([ctx.lon, ctx.lat]), 500)
    if b.empty:
        raise RuntimeError("MCD12Q1 sem dados para o ponto")
    df = pd.DataFrame({"ano": pd.to_datetime(b["time"], unit="ms").dt.year,
                       "classe_id": pd.to_numeric(b["LC_Type1"], errors="coerce").astype("Int64")})
    df["classe"] = df["classe_id"].map(IGBP)
    ctx.ref("MODIS/Terra+Aqua Land Cover Type Yearly L3 Global 500m (MCD12Q1 v061), via Google Earth Engine",
            "https://doi.org/10.5067/MODIS/MCD12Q1.061", "Uso livre (NASA EOSDIS)",
            "Friedl, M., Sulla-Menashe, D. (2022). MCD12Q1 MODIS/Terra+Aqua Land Cover Type Yearly L3 Global 500m SIN Grid V061.")
    return df.drop_duplicates("ano").sort_values("ano").reset_index(drop=True)


_PAIS: dict = {}


def pais_do_ponto(lat: float, lon: float) -> tuple[str, str]:
    """(codigo ISO de 2 letras, nome) pelo OpenStreetMap Nominatim."""
    return local_do_ponto(lat, lon)[:2]


def local_do_ponto(lat: float, lon: float) -> tuple[str, str, str]:
    """(codigo ISO do pais, nome do pais, "municipio ou condado, estado") pelo OpenStreetMap Nominatim."""
    k = (round(lat, 3), round(lon, 3))
    if k not in _PAIS:
        js = get("https://nominatim.openstreetmap.org/reverse",
                 params={"lat": lat, "lon": lon, "format": "jsonv2", "zoom": 10, "addressdetails": 1,
                         "accept-language": "en"}).json()
        end = js.get("address", {})
        lugar = (end.get("city") or end.get("town") or end.get("municipality") or end.get("county")
                 or end.get("state_district") or end.get("village") or "")
        estado = end.get("state", "")
        _PAIS[k] = (str(end.get("country_code", "")).upper(), end.get("country", ""),
                    ", ".join(x for x in (lugar, estado) if x))
    return _PAIS[k]


# ----------------------------------------------------------------------------------------
# 8. Harmonizacao diaria + indicadores
# ----------------------------------------------------------------------------------------
def radiacao_extraterrestre_mm(lat: float, dias_ano: np.ndarray) -> np.ndarray:
    """Ra em mm/dia equivalentes (FAO-56, eq. 21, x0.408)."""
    phi = math.radians(lat)
    dr = 1 + 0.033 * np.cos(2 * np.pi * dias_ano / 365)
    dec = 0.409 * np.sin(2 * np.pi * dias_ano / 365 - 1.39)
    ws = np.arccos(np.clip(-np.tan(phi) * np.tan(dec), -1, 1))
    ra = (24 * 60 / np.pi) * 0.0820 * dr * (ws * np.sin(phi) * np.sin(dec) + np.cos(phi) * np.cos(dec) * np.sin(ws))
    return 0.408 * ra


def harmonizar(ctx: Contexto, tabelas: dict[str, pd.DataFrame]) -> pd.DataFrame | None:
    if "power" not in tabelas:
        return None
    d = tabelas["power"].copy()
    ra = radiacao_extraterrestre_mm(ctx.lat, d["data"].dt.day_of_year.to_numpy())
    amp = (d["temp_max_c"] - d["temp_min_c"]).clip(lower=0)
    d["et0_hargreaves_mm"] = 0.0023 * (d["temp_media_c"] + 17.8) * np.sqrt(amp) * ra
    d["geada"] = d["temp_min_c"] <= 2.0
    d["calor_extremo"] = d["temp_max_c"] >= 35.0
    d["chuva_extrema"] = d["chuva_power_mm"] >= 50.0
    d["ano_safra"] = np.where(d["data"].dt.month >= 7, d["data"].dt.year, d["data"].dt.year - 1)

    if "imerg" in tabelas and len(tabelas["imerg"]) and tabelas["imerg"]["data"].dt.day.nunique() > 1:
        d = d.merge(tabelas["imerg"], on="data", how="left")  # so funde se for diario
    if "smap_l4" in tabelas:
        d = d.merge(tabelas["smap_l4"], on="data", how="left")
    if "chirps" in tabelas:
        d = d.merge(tabelas["chirps"], on="data", how="left")
    if "ndvi_modis" in tabelas:
        n = tabelas["ndvi_modis"][["data", "ndvi"]].dropna()
        d = pd.merge_asof(d.sort_values("data"), n.sort_values("data"), on="data",
                          direction="backward", tolerance=pd.Timedelta(days=16))
        d["solo_descoberto"] = d["ndvi"] < 0.3
    if "ndvi_hls" in tabelas:
        h = (tabelas["ndvi_hls"].dropna(subset=["ndvi"]).assign(data=lambda x: x["data"].dt.normalize())
             .groupby("data", as_index=False)["ndvi"].median().rename(columns={"ndvi": "ndvi_hls"}))
        d = pd.merge_asof(d.sort_values("data"), h, on="data", direction="backward", tolerance=pd.Timedelta(days=10))
    if "oni" in tabelas:
        d = d.merge(enso_por_safra(tabelas["oni"]), on="ano_safra", how="left")
    return d


def resumo_safras(d: pd.DataFrame, imerg: pd.DataFrame | None = None) -> pd.DataFrame:
    agg = {"chuva_power_mm": "sum", "et0_hargreaves_mm": "sum", "geada": "sum", "calor_extremo": "sum",
           "chuva_extrema": "sum"}
    if "ndvi" in d:
        agg["solo_descoberto"] = "mean"
    if "chuva_chirps_mm" in d:
        agg["chuva_chirps_mm"] = "sum"
    agg["data"] = "count"
    r = d.groupby("ano_safra").agg(agg).reset_index().rename(columns={"data": "dias"})
    r["safra_completa"] = r["dias"] >= 360  # jul a jun inteiro; as pontas do periodo ficam incompletas
    r["deficit_hidrico_mm"] = (r["et0_hargreaves_mm"] - r["chuva_power_mm"]).round(1)
    if "chuva_chirps_mm" in r:
        r["deficit_hidrico_chirps_mm"] = (r["et0_hargreaves_mm"] - r["chuva_chirps_mm"]).round(1)
    if imerg is not None and len(imerg):
        # chuva do satelite (mais fiel que o POWER no Cerrado); meses_imerg < 12 = safra sem cobertura completa
        m = imerg.copy()
        m["ano_safra"] = np.where(m["data"].dt.month >= 7, m["data"].dt.year, m["data"].dt.year - 1)
        mensal = m.groupby([m["ano_safra"], m["data"].dt.to_period("M")])["chuva_imerg_mm"].sum().reset_index()
        g = mensal.groupby("ano_safra").agg(chuva_imerg_mm=("chuva_imerg_mm", "sum"),
                                            meses_imerg=("chuva_imerg_mm", "count")).reset_index()
        r = r.merge(g, on="ano_safra", how="left")
        r["deficit_hidrico_imerg_mm"] = (r["et0_hargreaves_mm"] - r["chuva_imerg_mm"]).round(1)
        r.loc[r["meses_imerg"] < 12, "deficit_hidrico_imerg_mm"] = np.nan
    if "solo_descoberto" in r:
        r["pct_dias_solo_descoberto"] = (100 * r.pop("solo_descoberto")).round(1)
    if "enso_safra" in d:
        r = r.merge(d.groupby("ano_safra")["enso_safra"].first().reset_index(), on="ano_safra", how="left")
    return r


# ----------------------------------------------------------------------------------------
# principal
# ----------------------------------------------------------------------------------------
def main(argv=None):
    ap = argparse.ArgumentParser(description="Coleta de dados do Rotare para um talhao")
    ap.add_argument("--lat", type=float, required=True)
    ap.add_argument("--lon", type=float, required=True)
    ap.add_argument("--nome", default="talhao_demo")
    ap.add_argument("--inicio", default="2014-01-01")
    ap.add_argument("--fim", default=f"{date.today().year - 1}-12-31")
    ap.add_argument("--saida", default="dados")
    ap.add_argument("--fontes", default="power,power_historico,oni,solo,relevo,ecocrop,calendario_fao,zarc,sidra,"
                                        "chirps,imerg_gee,modis,smap,uso_terra,mapbiomas",
                    help="lista separada por virgula. Fontes so do Brasil (zarc, sidra, mapbiomas) sao puladas fora "
                         "dele. Alternativas: imerg (earthaccess), appeears e hls (fila do AppEEARS)")
    ap.add_argument("--ciclo-dias", type=int, default=120,
                    help="ciclo de referencia para a aptidao ECOCROP (limitado a faixa GMIN-GMAX de cada cultura)")
    ap.add_argument("--inicio-safra", type=int, default=0,
                    help="mes em que comeca o ano-safra do lugar (padrao: 7 no hemisferio sul, 1 no norte; "
                         "ex.: 5 no Punjab, onde o ano agricola junta arroz e trigo)")
    ap.add_argument("--pais", default="auto", help="codigo ISO do pais (padrao: descobre pelo lat/lon)")
    ap.add_argument("--chirps-inicio", default="1981-01-01",
                    help="inicio da serie CHIRPS (o padrao cobre o El Nino de 1997/98)")
    ap.add_argument("--geocodigo", default=None,
                    help="codigo IBGE do municipio para o ZARC (padrao: descobre pelo lat/lon)")
    ap.add_argument("--imerg", choices=["mensal", "diario"], default="mensal")
    ap.add_argument("--sem-smap", action="store_true")
    ap.add_argument("--refazer", action="store_true", help="baixa de novo mesmo o que ja esta em cache")
    ap.add_argument("--mapbiomas-asset",
                    default="projects/mapbiomas-public/assets/brazil/lulc/collection9/mapbiomas_collection90_integration_v1")
    a = ap.parse_args(argv)
    carregar_env()

    ctx = Contexto(a.lat, a.lon, date.fromisoformat(a.inicio), date.fromisoformat(a.fim),
                   Path(a.saida) / a.nome, a.nome)
    ctx.saida.mkdir(parents=True, exist_ok=True)
    fontes = [f.strip() for f in a.fontes.split(",") if f.strip()]
    tabelas: dict[str, pd.DataFrame] = {}
    if a.pais == "auto":
        try:
            a.pais, nome_pais = pais_do_ponto(ctx.lat, ctx.lon)
        except Exception as e:  # noqa: BLE001
            a.pais, nome_pais = "", ""
            log(f"  pais nao identificado ({str(e)[:60]})")
    else:
        nome_pais = a.pais
    so_brasil = {"zarc", "sidra", "mapbiomas"}

    tarefas = {
        "power": lambda: {"power": coletar_power(ctx)},
        "power_historico": lambda: {"power_historico": coletar_power(
            replace(ctx, inicio=date(1981, 1, 1), fim=ctx.inicio - timedelta(days=1)))},
        "oni": lambda: {"oni": coletar_oni(ctx)},
        "appeears": lambda: coletar_appeears(ctx, incluir_smap=not a.sem_smap),
        "hls": lambda: coletar_hls(ctx),
        "ecocrop": lambda: coletar_ecocrop(ctx, tabelas, a.ciclo_dias),
        "calendario_fao": lambda: {"calendario_fao": coletar_calendario_fao(ctx, a.pais)},
        "zarc": lambda: {"zarc": coletar_zarc(ctx, a.geocodigo)},
        "chirps": lambda: coletar_chirps(ctx, tabelas, a.chirps_inicio),
        "sidra": lambda: {"sidra_pam": coletar_sidra(ctx, a.geocodigo)},
        "imerg": lambda: {"imerg": coletar_imerg(ctx, a.imerg)},
        "solo": lambda: {"solo": coletar_solo(ctx)},
        "relevo": lambda: {"relevo": coletar_relevo(ctx)},
        "mapbiomas": lambda: {"mapbiomas": coletar_mapbiomas(ctx, a.mapbiomas_asset)},
        "modis": lambda: {"ndvi_modis": coletar_modis_gee(ctx)},
        "smap": lambda: {"smap_l4": coletar_smap_gee(ctx)},
        "imerg_gee": lambda: {"imerg": coletar_imerg_gee(ctx)},
        "uso_terra": lambda: {"uso_terra_modis": coletar_uso_terra_gee(ctx)},
    }

    saidas_da_fonte = {"appeears": ["ndvi_modis"], "hls": ["ndvi_hls"],
                       "ecocrop": ["ecocrop_parametros", "aptidao_ecocrop"],
                       "chirps": ["chirps", "chirps_safras"], "sidra": ["sidra_pam"],
                       "modis": ["ndvi_modis"], "smap": ["smap_l4"], "imerg_gee": ["imerg"],
                       "uso_terra": ["uso_terra_modis"]}  # o smap_l4 do appeears e opcional
    fontes_de: dict[str, list[str]] = {"smap_l4": ["appeears"]}
    for f_, ns in saidas_da_fonte.items():
        for n in ns:
            fontes_de.setdefault(n, []).append(f_)
    chave = f"{ctx.lat},{ctx.lon},{ctx.inicio},{ctx.fim}"
    cache_arq = ctx.saida / "cache.json"
    cache = json.loads(cache_arq.read_text(encoding="utf-8")) if cache_arq.exists() else {}

    def em_cache(f: str) -> bool:
        arqs = [ctx.saida / f"{n}.parquet" for n in saidas_da_fonte.get(f, [f])]
        return cache.get(f) == chave and all(x.exists() for x in arqs)

    log(f"Rotare | ponto ({ctx.lat}, {ctx.lon}) | {ctx.inicio} a {ctx.fim} | saida em {ctx.saida}")
    for f in fontes:
        if f not in tarefas:
            log(f"fonte desconhecida: {f}")
            continue
        if f in so_brasil and a.pais != "BR":
            log(f"> {f}: so existe para o Brasil, pulando ({nome_pais or 'pais desconhecido'})")
            continue
        if not a.refazer and em_cache(f):
            log(f"> {f}: ja baixado, pulando (use --refazer para baixar de novo)")
            for n in saidas_da_fonte.get(f, [f]) + (["smap_l4"] if f == "appeears" else []):
                arq = ctx.saida / f"{n}.parquet"
                if arq.exists():  # carrega ja, pois fontes seguintes (ex.: ecocrop) dependem dela
                    tabelas[n] = pd.read_parquet(arq)
                    ctx.resumo[n] = f"cache ({len(tabelas[n])} linhas)"
            continue
        log(f"> {f}")
        t0 = time.time()
        try:
            for nome, df in tarefas[f]().items():
                tabelas[nome] = df
                ctx.salvar(df, f"{nome}.parquet")
                ctx.resumo[nome] = f"ok, {len(df)} linhas ({time.time() - t0:.0f}s)"
                log(f"  {nome}: {len(df)} linhas")
            cache[f] = chave
            cache_arq.write_text(json.dumps(cache, indent=2), encoding="utf-8")
        except Exception as e:  # noqa: BLE001
            ctx.resumo[f] = f"FALHOU: {e}"
            log(f"  {f} falhou: {e}")

    # fontes nao pedidas nesta rodada, mas ja baixadas para o mesmo ponto e periodo, entram na base
    for nome in ("power", "oni", "ndvi_modis", "smap_l4", "ndvi_hls", "imerg", "solo", "relevo", "mapbiomas",
                 "ecocrop_parametros", "aptidao_ecocrop", "calendario_fao", "zarc",
                 "chirps", "chirps_safras", "sidra_pam", "uso_terra_modis"):
        arq = ctx.saida / f"{nome}.parquet"
        if nome not in tabelas and arq.exists() and any(cache.get(f_) == chave for f_ in fontes_de.get(nome, [nome])):
            tabelas[nome] = pd.read_parquet(arq)
            ctx.resumo.setdefault(nome, f"cache ({len(tabelas[nome])} linhas)")

    base = harmonizar(ctx, tabelas)
    if base is not None:
        ctx.salvar(base, "base_diaria.parquet")
        safras = resumo_safras(base, tabelas.get("imerg"))
        ctx.salvar(safras, "resumo_safras.parquet")
        ctx.resumo["base_diaria"] = f"ok, {len(base)} dias, {base.shape[1]} colunas"
        if "ndvi" in base:
            amp = base["ndvi"].quantile(0.95) - base["ndvi"].quantile(0.05)
            if amp < 0.3:
                log("  ATENCAO: NDVI quase sem variacao. O ponto pode nao estar em lavoura (mata, cidade, agua).")

    antigo = ctx.saida / "manifesto.json"
    if antigo.exists():  # mantem as referencias de rodadas anteriores
        bruto = antigo.read_bytes()
        try:
            texto = bruto.decode("utf-8")
        except UnicodeDecodeError:
            texto = bruto.decode("cp1252")  # manifesto antigo gravado com o padrao do Windows
        vistas = {r["fonte"] for r in ctx.referencias}
        for r in json.loads(texto).get("referencias", []):
            if r["fonte"] not in vistas:
                ctx.referencias.append(r)
                vistas.add(r["fonte"])

    manifesto = {
        "projeto": "Rotare | Datanauts Brasil | NASA Space Apps Challenge 2026",
        "gerado_em": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "ponto": {"nome": ctx.nome, "lat": ctx.lat, "lon": ctx.lon, "pais": a.pais, "pais_nome": nome_pais, "local": _PAIS.get((round(ctx.lat, 3), round(ctx.lon, 3)), ("", "", ""))[2],
                  "mes_inicio_safra": a.inicio_safra or (7 if ctx.lat < 0 else 1)},
        "periodo": [ctx.inicio.isoformat(), ctx.fim.isoformat()],
        "resultado": ctx.resumo,
        "referencias": ctx.referencias,
    }
    (ctx.saida / "manifesto.json").write_text(json.dumps(manifesto, ensure_ascii=False, indent=2), encoding="utf-8")

    print("\n===== RESUMO =====")
    for k, v in ctx.resumo.items():
        print(f"  {k:18s} {v}")
    print(f"\nArquivos em: {ctx.saida.resolve()}")
    return 0 if not any(str(v).startswith("FALHOU") for v in ctx.resumo.values()) else 1


if __name__ == "__main__":
    sys.exit(main())
